114. 	/**
115. 	 * Read-only fetch of the Copilot CLI's own configured MCP servers. Returns
116. 	 * {} when the capability is unavailable or the RPC fails — the panel simply
117. 	 * omits the Copilot section rather than erroring.
118. 	 */
119. 	private async fetchCopilotConfiguredServers(): Promise<Record<string, any>> {
120. 		if (!this.cliCapability?.supportsMcpConfigRpc() || !this.mcpConfigListProvider) {
121. 			return {};
122. 		}
123. 		try {
124. 			return await this.mcpConfigListProvider();
125. 		} catch (err: any) {
126. 			this.logger.warn(`[MCP] mcp.config.list RPC failed: ${err?.message ?? err}`);
127. 			return {};
128. 		}
129. 	}
