131. 	/**
132. 	 * Build the full /mcp panel server list (user + managed + imported + Copilot
133. 	 * config) and push it to the webview. Used by /mcp and to refresh after edits.
134. 	 */
135. 	private async buildAndSendMcpStatus(): Promise<void> {
136. 		try {
137. 			const mcpRegistry = new ManagedMCPRegistry();
138. 			const userConfig = vscode.workspace.getConfiguration('copilotCLI')
139. 				.get<Record<string, any>>('mcpServers', {});
140. 			const managedServers = mcpRegistry.getManagedServers();
141. 			// Display set includes DISABLED user servers (with `enabled` preserved)
142. 			// so they remain visible/re-enableable — unlike the SDK feed, which
143. 			// filters them. See getMCPServersForDisplay vs getEnabledMCPServers.
144. 			const userDisplay = this.mcpConfigService!.getMCPServersForDisplay(userConfig);
145. 			const imported = this.importedServersProvider?.() ?? {};
146. 			// Precedence for display: imported < user < managed.
147. 			const allServers = { ...imported, ...userDisplay, ...managedServers };
148. 
149. 			// A key is "imported" only when it isn't shadowed by a user or managed entry.
150. 			const sources: Record<string, McpServerSource> = {};
151. 			for (const key of Object.keys(imported)) {
152. 				if (!(key in userDisplay) && !(key in managedServers)) {
153. 					sources[key] = 'imported';
154. 				}
155. 			}
156. 
157. 			// Read-only view of the Copilot CLI's own configured servers.
158. 			const copilotServers = await this.fetchCopilotConfiguredServers();
159. 
160. 			if (this.cliCapability?.supportsMcpListRpc() && this.mcpListProvider) {
161. 				try {
162. 					const sdkList = await this.mcpListProvider();
163. 					this.logger.debug(`[MCP] Raw SDK list: ${JSON.stringify(sdkList).substring(0, 300)}`);
164. 					const servers = mergeCopilotConfigList(
165. 						mergeMcpListWithConfig(allServers, sdkList, sources),
166. 						copilotServers
167. 					);
168. 					this.logger.info(`[MCP] Sending mcpStatus (live): ${servers.map(s => `${s.name}=${s.status}`).join(', ')}`);
169. 					this.rpcRouter!.sendMcpStatus(servers);
170. 					return;
171. 				} catch (rpcErr: any) {
172. 					this.logger.warn(`[MCP] mcp.list RPC failed, falling back to config view: ${rpcErr.message}`);
173. 				}
174. 			}
175. 
176. 			const knownTools = getBackendState().getMcpServerTools();
177. 			const knownStatuses = getBackendState().getMcpServerStatuses();
178. 			const capabilityFlags = {
179. 				supportsMcpStatusEvents: () => this.cliCapability?.supportsMcpStatusEvents() ?? false,
180. 			};
181. 
182. 			const servers = mergeCopilotConfigList(
183. 				buildMcpServerStatusList(allServers, knownTools, knownStatuses, capabilityFlags, sources),
184. 				copilotServers
185. 			);
186. 
187. 			this.logger.info(`[MCP] Sending mcpStatus: ${servers.map(s => `${s.name}=${s.status}`).join(', ')}`);
188. 			this.rpcRouter!.sendMcpStatus(servers);
189. 		} catch (err: any) {
190. 			this.logger.error(`[MCP] Failed to build server status: ${err.message}`);
191. 			this.rpcRouter!.sendMcpStatus([]);
192. 		}
193. 	}
194. 
195. 	/**
196. 	 * Apply an add/edit/remove/setEnabled action to the extension's own
197. 	 * `copilotCLI.mcpServers` setting. This is the ONLY MCP config the extension
198. 	 * writes — managed/imported/Copilot servers are never mutated here.
199. 	 */
200. 	private async handleMcpServerAction(payload: McpServerActionPayload): Promise<void> {
201. 		const { action, config, enabled } = payload;
202. 		// Normalize names once (validation trims internally; the persisted key must
203. 		// match the validated name, not a whitespace-padded raw payload value).
204. 		const name = (payload.name ?? '').trim();
205. 		const originalName = payload.originalName?.trim();
206. 		this.logger.info(`[MCP] server action: ${action} "${name}"`);
207. 		try {
208. 			const cfg = vscode.workspace.getConfiguration('copilotCLI');
209. 			const current = cfg.get<Record<string, any>>('mcpServers', {});
210. 			let next: Record<string, any>;
211. 
212. 			if (action === 'add') {
213. 				const existing = Object.keys(current);
214. 				const validation = validateMcpServerInput({ name, ...(config ?? {}) } as McpServerInput, existing);
215. 				if (!validation.valid) {
216. 					this.rpcRouter!.sendMcpServerActionResult({ success: false, action, name, errors: validation.errors });
217. 					return;
218. 				}
219. 				next = addMcpServerToConfig(current, name, config ?? {});
220. 			} else if (action === 'edit') {
221. 				const prevName = originalName ?? name;
222. 				const existing = Object.keys(current).filter(k => k !== prevName);
223. 				const validation = validateMcpServerInput({ name, ...(config ?? {}) } as McpServerInput, existing);
224. 				if (!validation.valid) {
225. 					this.rpcRouter!.sendMcpServerActionResult({ success: false, action, name, errors: validation.errors });
226. 					return;
227. 				}
228. 				// Preserve the prior enabled state (the form has no enabled field, so
229. 				// editing/renaming a disabled server must not silently re-enable it).
230. 				const merged = preserveEnabledFlag(current[prevName], config ?? {});
231. 				// Support rename: drop the old key, then write the new one.
232. 				next = editMcpServerInConfig(removeMcpServerFromConfig(current, prevName), name, merged);
233. 			} else if (action === 'remove') {
234. 				next = removeMcpServerFromConfig(current, name);
235. 			} else { // setEnabled
236. 				next = setMcpServerEnabled(current, name, enabled ?? true);
237. 			}
238. 
239. 			await cfg.update('mcpServers', next, vscode.ConfigurationTarget.Global);
240. 			this.rpcRouter!.sendMcpServerActionResult({ success: true, action, name });
241. 			await this.buildAndSendMcpStatus();
242. 		} catch (err: any) {
243. 			this.logger.error(`[MCP] server action failed: ${err?.message ?? err}`);
244. 			this.rpcRouter!.sendMcpServerActionResult({ success: false, action, name, errors: [String(err?.message ?? err)] });
245. 		}
246. 	}
